package io.github.nbauma109.staticanalysis;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;

/**
 * Limits analysis to sources outside the configured build output directory.
 * Generated bytecode and dependencies remain available on the analysis classpath.
 */
final class SourceAnalysisScope {

    private final Path projectDirectory;
    private final Path buildDirectory;

    SourceAnalysisScope(Path projectDirectory, Path buildDirectory) {
        this.projectDirectory = projectDirectory.toAbsolutePath().normalize();
        this.buildDirectory = this.projectDirectory.resolve(buildDirectory).normalize();
    }

    boolean includes(Path source) {
        return !projectDirectory.resolve(source).normalize().startsWith(buildDirectory);
    }

    List<String> sourceRoots(Iterable<String> roots) {
        List<String> retained = new ArrayList<>();
        for (String root : roots) {
            if (includes(Path.of(root))) {
                retained.add(root);
            }
        }
        return retained;
    }

    List<Path> javaFiles(Iterable<String> roots) throws IOException {
        List<Path> files = new ArrayList<>();
        for (String root : sourceRoots(roots)) {
            Path directory = projectDirectory.resolve(root).normalize();
            if (Files.isDirectory(directory)) {
                try (Stream<Path> entries = Files.walk(directory)) {
                    for (Path file : entries.filter(Files::isRegularFile)
                            .filter(path -> path.toString().endsWith(".java"))
                            .filter(this::includes).sorted().toList()) {
                        files.add(file);
                    }
                }
            }
        }
        return files;
    }

    EclipseCleanupRunner.Result retainFindings(EclipseCleanupRunner.Result result) {
        List<EclipseCleanupRunner.Diagnostic> findings = new ArrayList<>();
        for (EclipseCleanupRunner.Diagnostic finding : result.findings()) {
            if (includes(Path.of(finding.file()))) {
                findings.add(finding);
            }
        }
        return new EclipseCleanupRunner.Result(List.copyOf(findings), result.suppressed());
    }
}
